def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]

    marker = next((c for c, v in enumerate(grid[0]) if v == 5), 0)
    wall = next((c for c, v in enumerate(grid[0]) if v == 4), 7)
    col = marker - wall - 1
    row = 0
    out[row][col] = 5

    left, right = [], []
    for y in range(0, h, 4):
        for x0, seq in ((0, left), (4, right)):
            colors = {
                grid[yy][xx]
                for yy in range(y, min(y + 3, h))
                for xx in range(x0, min(x0 + 3, len(grid[0])))
                if grid[yy][xx] not in (0, 4, 5)
            }
            if colors:
                seq.append(next(iter(colors)))

    for color in left + right:
        if color == 6:
            for k in range(1, 3):
                rr = row + k
                if 0 <= rr < h and 0 <= col < 7:
                    out[rr][col] = color
            row += 2
        else:
            length = {1: 3, 2: 2, 3: 4}.get(color, 1)
            step = 1 if color == 1 else -1
            rr = row + 1
            for k in range(length):
                cc = col + step * k
                if 0 <= rr < h and 0 <= cc < 7:
                    out[rr][cc] = color
            row = rr
            col += step * (length - 1)

    return out
